steps.script:
var c=document.querySelector('#redeem-failed .callout.warning');
var p=document.createElement('span'); document.body.appendChild(p);
p.style.backgroundColor='var(--warn-bg)'; var warn=getComputedStyle(p).backgroundColor;
p.style.backgroundColor='var(--danger-bg)'; var danger=getComputedStyle(p).backgroundColor;
p.remove();
var got=getComputedStyle(c).backgroundColor;
return JSON.stringify({isWarn:got===warn, isDanger:got===danger});
